/**
 * 产品路由
 */

const express = require('express');
const router = express.Router();
const { body, query, validationResult } = require('express-validator');
const { Product, ProductCategory, ProductGrade, ProductOrigin, ProductSpec } = require('../models');
const { SuccessResponse, ListResponse, ErrorResponse } = require('../utils/response');
const { authenticate, authorize } = require('../middleware/auth');

// 获取产品列表
router.get('/', async (req, res) => {
  try {
    const { page = 1, pageSize = 20, categoryId, gradeId, year, keyword, status } = req.query;
    const offset = (page - 1) * pageSize;

    const where = {};
    if (categoryId) where.category_id = categoryId;
    if (gradeId) where.grade_id = gradeId;
    if (year) where.year = year;
    if (status !== undefined) where.status = status;
    if (keyword) {
      where.name = { [require('sequelize').Op.like]: `%${keyword}%` };
    }

    const { rows: list, count } = await Product.findAndCountAll({
      where,
      include: [
        { model: ProductCategory, as: 'category', attributes: ['id', 'name', 'code'] },
        { model: ProductGrade, as: 'grade', attributes: ['id', 'name', 'code'] },
        { model: ProductOrigin, as: 'origin', attributes: ['id', 'name', 'code'] },
        { model: ProductSpec, as: 'spec', attributes: ['id', 'name', 'unit'] }
      ],
      limit: parseInt(pageSize),
      offset,
      order: [['sort_order', 'ASC'], ['id', 'DESC']]
    });

    res.json(new ListResponse(list, { page: parseInt(page), pageSize: parseInt(pageSize), total: count }));
  } catch (error) {
    next(error);
  }
});

// 获取产品选项(下拉用)
router.get('/options', async (req, res) => {
  try {
    const categories = await ProductCategory.findAll({ where: { status: 1 }, order: [['sort_order']] });
    const grades = await ProductGrade.findAll({ where: { status: 1 }, order: [['sort_order']] });
    const origins = await ProductOrigin.findAll({ where: { status: 1 }, order: [['sort_order']] });
    const specs = await ProductSpec.findAll({ where: { status: 1 }, order: [['sort_order']] });

    res.json(new SuccessResponse({ categories, grades, origins, specs }));
  } catch (error) {
    next(error);
  }
});

// 获取产品详情
router.get('/:id', async (req, res) => {
  try {
    const product = await Product.findByPk(req.params.id, {
      include: [
        { model: ProductCategory, as: 'category' },
        { model: ProductGrade, as: 'grade' },
        { model: ProductOrigin, as: 'origin' },
        { model: ProductSpec, as: 'spec' }
      ]
    });

    if (!product) {
      return res.status(404).json(new ErrorResponse(404, '产品不存在'));
    }

    res.json(new SuccessResponse(product));
  } catch (error) {
    next(error);
  }
});

// 创建产品
router.post('/', authenticate, authorize('admin', 'manager'), [
  body('code').notEmpty().isLength({ max: 30 }),
  body('name').notEmpty().isLength({ max: 100 }),
  body('category_id').optional().isInt(),
  body('grade_id').optional().isInt(),
  body('year').optional().isInt()
], async (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ code: 400, message: '参数错误', errors: errors.array() });
    }

    const product = await Product.create(req.body);
    res.json(new SuccessResponse(product, '创建成功'));
  } catch (error) {
    next(error);
  }
});

// 更新产品
router.put('/:id', authenticate, authorize('admin', 'manager'), async (req, res) => {
  try {
    const product = await Product.findByPk(req.params.id);
    if (!product) {
      return res.status(404).json(new ErrorResponse(404, '产品不存在'));
    }

    await product.update(req.body);
    res.json(new SuccessResponse(product, '更新成功'));
  } catch (error) {
    next(error);
  }
});

// 删除产品
router.delete('/:id', authenticate, authorize('admin'), async (req, res) => {
  try {
    const product = await Product.findByPk(req.params.id);
    if (!product) {
      return res.status(404).json(new ErrorResponse(404, '产品不存在'));
    }

    await product.destroy();
    res.json(new SuccessResponse(null, '删除成功'));
  } catch (error) {
    next(error);
  }
});

module.exports = router;

