/**
 * 认证中间件
 */

const jwt = require('jsonwebtoken');
const config = require('../config/jwt');
const { User } = require('../models');
const { ErrorResponse } = require('../utils/response');

// 验证Token
const authenticate = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json(new ErrorResponse(401, '未提供认证Token'));
    }

    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, config.secret);

    const user = await User.findByPk(decoded.userId, {
      attributes: ['id', 'username', 'role', 'status']
    });

    if (!user) {
      return res.status(401).json(new ErrorResponse(401, '用户不存在'));
    }

    if (user.status !== 1) {
      return res.status(403).json(new ErrorResponse(403, '账户已被禁用'));
    }

    req.user = user;
    next();
  } catch (error) {
    return res.status(401).json(new ErrorResponse(401, '认证失败'));
  }
};

// 角色权限检查
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json(new ErrorResponse(401, '未登录'));
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json(new ErrorResponse(403, '没有操作权限'));
    }

    next();
  };
};

module.exports = { authenticate, authorize };

