        volume: acc.volume + (p.volume || 0),
        turnover: acc.turnover + (p.turnover || 0)
      }), { avg: 0, max: 0, min: 0, volume: 0, turnover: 0 });

      statistics.avgPrice = (sum.avg / prices.length).toFixed(2);
      statistics.maxPrice = sum.max;
      statistics.minPrice = sum.min;
      statistics.totalVolume = sum.volume;
      statistics.totalTurnover = sum.turnover.toFixed(2);
