  try {
    const { date } = req.query;
    const targetDate = date || new Date().toISOString().split('T')[0];

    const prices = await DailyPrice.findAll({
      where: { price_date: targetDate, status: 1 },
      include: [{
        model: Product,
        as: 'product',
        include: [{ model: ProductCategory, as: 'category' }]
      }]
    });

    const stats = {};
    prices.forEach(p => {
      const categoryName = p.product?.category?.name || '未分类';
      if (!stats[categoryName]) {
        stats[categoryName] = { count: 0, totalVolume: 0, totalTurnover: 0 };
      }
      stats[categoryName].count++;
      stats[categoryName].totalVolume += p.volume || 0;
      stats[categoryName].totalTurnover += p.turnover || 0;
    });

    res.json(new SuccessResponse(stats));
  } catch (error) {
    next(error);
  }
});

