 */

const express = require('express');
const router = express.Router();
const { Op, fn, col } = require('sequelize');
const { DailyPrice, Product, DailyStatistics, ProductCategory } = require('../models');
const { SuccessResponse } = require('../utils/response');

// 日统计
router.get('/daily', async (req, res) => {
  try {
    const { date } = req.query;
    const targetDate = date || new Date().toISOString().split('T')[0];

    // 先查日统计表
    let stats = await DailyStatistics.findOne({
      where: { stat_date: targetDate }
    });

    // 如果没有日统计，实时计算
    if (!stats) {
      const prices = await DailyPrice.findAll({
        where: { price_date: targetDate, status: 1 }
      });

      if (prices.length > 0) {
        const rising = prices.filter(p => p.price_change_percent > 0).length;
        const falling = prices.filter(p => p.price_change_percent < 0).length;
        const totalVolume = prices.reduce((sum, p) => sum + (p.volume || 0), 0);
        const totalTurnover = prices.reduce((sum, p) => sum + (p.turnover || 0), 0);

        stats = {
          stat_date: targetDate,
          total_products: prices.length,
          rising_count: rising,
          falling_count: falling,
          flat_count: prices.length - rising - falling,
          rising_percent: ((rising / prices.length) * 100).toFixed(2),
          avg_price: (prices.reduce((sum, p) => sum + (p.price_avg || 0), 0) / prices.length).toFixed(2),
          max_price: Math.max(...prices.map(p => p.price_avg || 0)),
          min_price: Math.min(...prices.map(p => p.price_avg || 0)),
          total_volume: totalVolume,
          total_turnover: totalTurnover.toFixed(2)
        };
      }
    }

    res.json(new SuccessResponse(stats));
  } catch (error) {
    next(error);
  }
});

// 趋势数据
router.get('/trend', async (req, res) => {
  try {
    const { productId, startDate, endDate, period = 'day' } = req.query;

    const where = { status: 1 };
    if (productId) where.product_id = productId;
    if (startDate) where.price_date = { [Op.gte]: startDate };
    if (endDate) where.price_date = { ...where.price_date, [Op.lte]: endDate };

    const prices = await DailyPrice.findAll({
      where,
      include: productId ? [] : [{
        model: Product,
        as: 'product',
        attributes: ['id', 'name']
      }],
      order: [['price_date', 'ASC']]
    });

    res.json(new SuccessResponse({
      trend: prices.map(p => ({
        date: p.price_date,
        avgPrice: p.price_avg,
        volume: p.volume,
        turnover: p.turnover
      }))
    }));
  } catch (error) {
    next(error);
  }
});

// 排行榜
