/**
 * Sequelize Models - 用户相关
 */

const { DataTypes } = require('sequelize');
const bcrypt = require('bcryptjs');
const { sequelize } = require('../config/database');

// 用户
const User = sequelize.define('User', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  username: { type: DataTypes.STRING(50), allowNull: false, unique: true },
  password: { type: DataTypes.STRING(255), allowNull: false },
  real_name: { type: DataTypes.STRING(50) },
  phone: { type: DataTypes.STRING(20) },
  email: { type: DataTypes.STRING(100) },
  role: { type: DataTypes.STRING(20), defaultValue: 'viewer' },
  status: { type: DataTypes.TINYINT, defaultValue: 1 },
  last_login_at: { type: DataTypes.DATE }
}, { 
  tableName: 'users',
  timestamps: false,
  hooks: {
    beforeCreate: async (user) => {
      if (user.password) {
        user.password = await bcrypt.hash(user.password, 10);
      }
    },
    beforeUpdate: async (user) => {
      if (user.changed('password')) {
        user.password = await bcrypt.hash(user.password, 10);
      }
    }
  }
});

// 操作日志
const OperationLog = sequelize.define('OperationLog', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  user_id: { type: DataTypes.INTEGER },
  action: { type: DataTypes.STRING(50), allowNull: false },
  module: { type: DataTypes.STRING(50), allowNull: false },
  content: { type: DataTypes.TEXT },
  ip: { type: DataTypes.STRING(50) }
}, { tableName: 'operation_logs', timestamps: false });

// 系统配置
const SystemConfig = sequelize.define('SystemConfig', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  key: { type: DataTypes.STRING(100), allowNull: false, unique: true },
  value: { type: DataTypes.TEXT },
  type: { type: DataTypes.STRING(20), defaultValue: 'string' },
  description: { type: DataTypes.STRING(200) }
}, { tableName: 'system_config', timestamps: false });

module.exports = { User, OperationLog, SystemConfig };

/**
 * Models 统一导出
 */

const { ProductCategory, ProductGrade, ProductOrigin, ProductSpec, ProductBrand, Product } = require('./product');
const { DataSource, DailyPrice, DailyStatistics } = require('./price');
const { User, OperationLog, SystemConfig } = require('./user');

module.exports = {
  ProductCategory,
  ProductGrade,
  ProductOrigin,
  ProductSpec,
  ProductBrand,
  Product,
  DataSource,
  DailyPrice,
  DailyStatistics,
  User,
  OperationLog,
  SystemConfig
};

