              style={{ width: 100 }}
              options={options.grades?.map(g => ({ label: g.name, value: g.id }))}
              onChange={(v) => handleFilter('gradeId', v)}
            />
            <Select
              placeholder="年份"
              allowClear
              style={{ width: 100 }}
