const { Sequelize } = require('sequelize');
const path = require('path');

// 读取环境变量
require('dotenv').config({ path: path.join(__dirname, '../../.env') });

const dbType = process.env.DB_TYPE || 'sqlite';
let sequelize;

if (dbType === 'sqlite') {
  // SQLite开发环境配置 (使用 sql.js)
  const sqlitePath = path.join(__dirname, '../../data/liupao_price.db');
  sequelize = new Sequelize({
    dialect: 'sqlite',
    storage: sqlitePath,
    logging: false,
    pool: {
      max: 5,
      min: 0,
      acquire: 30000,
      idle: 10000
    }
  });
} else {
  // MySQL生产环境配置
  sequelize = new Sequelize(
    process.env.DB_NAME || 'liupao_price',
    process.env.DB_USER || 'root',
    process.env.DB_PASSWORD || '',
    {
      host: process.env.DB_HOST || 'localhost',
      port: process.env.DB_PORT || 3306,
      dialect: 'mysql',
      logging: console.log,
      pool: {
        max: 10,
        min: 0,
        acquire: 30000,
        idle: 10000
      },
      timezone: '+08:00',
      define: {
        timestamps: true,
        underscored: true
      }
    }
  );
}

// 测试数据库连接
const testConnection = async () => {
  try {
    await sequelize.authenticate();
    logger.info('✅ 数据库连接成功');
  } catch (error) {
    logger.error('❌ 数据库连接失败:', error.message);
    process.exit(1);
  }
};

module.exports = { sequelize, testConnection };

