/**
 * Sequelize Models - 产品相关
 */

const { Sequelize, DataTypes } = require('sequelize');
const { sequelize } = require('../config/database');

// 产品类别
const ProductCategory = sequelize.define('ProductCategory', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING(50), allowNull: false },
  code: { type: DataTypes.STRING(20), allowNull: false, unique: true },
  sort_order: { type: DataTypes.INTEGER, defaultValue: 0 },
  status: { type: DataTypes.TINYINT, defaultValue: 1 }
}, { tableName: 'product_categories', timestamps: false });

// 产品等级
const ProductGrade = sequelize.define('ProductGrade', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING(20), allowNull: false },
  code: { type: DataTypes.STRING(20), allowNull: false, unique: true },
  sort_order: { type: DataTypes.INTEGER, defaultValue: 0 },
  status: { type: DataTypes.TINYINT, defaultValue: 1 }
}, { tableName: 'product_grades', timestamps: false });

// 产地
const ProductOrigin = sequelize.define('ProductOrigin', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING(50), allowNull: false },
  code: { type: DataTypes.STRING(20), allowNull: false, unique: true },
  region: { type: DataTypes.STRING(50) },
  sort_order: { type: DataTypes.INTEGER, defaultValue: 0 },
  status: { type: DataTypes.TINYINT, defaultValue: 1 }
}, { tableName: 'product_origins', timestamps: false });

// 规格
const ProductSpec = sequelize.define('ProductSpec', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING(50), allowNull: false },
  unit: { type: DataTypes.STRING(20) },
  weight: { type: DataTypes.DECIMAL(10, 3) },
  sort_order: { type: DataTypes.INTEGER, defaultValue: 0 },
  status: { type: DataTypes.TINYINT, defaultValue: 1 }
}, { tableName: 'product_specs', timestamps: false });

// 品牌
const ProductBrand = sequelize.define('ProductBrand', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING(100), allowNull: false },
  code: { type: DataTypes.STRING(30), allowNull: false, unique: true },
  contact: { type: DataTypes.STRING(100) },
  address: { type: DataTypes.TEXT },
  status: { type: DataTypes.TINYINT, defaultValue: 1 }
}, { tableName: 'product_brands', timestamps: false });

// 产品
const Product = sequelize.define('Product', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  code: { type: DataTypes.STRING(30), allowNull: false, unique: true },
  name: { type: DataTypes.STRING(100), allowNull: false },
  year: { type: DataTypes.INTEGER },
  storage_type: { type: DataTypes.STRING(20) },
  description: { type: DataTypes.TEXT },
  image_url: { type: DataTypes.STRING(500) },
  status: { type: DataTypes.TINYINT, defaultValue: 1 },
  sort_order: { type: DataTypes.INTEGER, defaultValue: 0 }
}, { tableName: 'products', timestamps: false });

// 关联关系
Product.belongsTo(ProductCategory, { foreignKey: 'category_id', as: 'category' });
Product.belongsTo(ProductGrade, { foreignKey: 'grade_id', as: 'grade' });
Product.belongsTo(ProductOrigin, { foreignKey: 'origin_id', as: 'origin' });
Product.belongsTo(ProductSpec, { foreignKey: 'spec_id', as: 'spec' });
Product.belongsTo(ProductBrand, { foreignKey: 'brand_id', as: 'brand' });

module.exports = {
  ProductCategory,
  ProductGrade,
  ProductOrigin,
  ProductSpec,
  ProductBrand,
  Product
};

