 */

const { Sequelize, DataTypes } = require('sequelize');
const { sequelize } = require('../config/database');
const { Product } = require('./product');

// 数据来源
const DataSource = sequelize.define('DataSource', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING(100), allowNull: false },
  type: { type: DataTypes.STRING(20), allowNull: false },
  api_url: { type: DataTypes.STRING(500) },
  api_key: { type: DataTypes.STRING(255) },
  api_secret: { type: DataTypes.STRING(255) },
  auth_type: { type: DataTypes.STRING(20), defaultValue: 'none' },
  selector_config: { type: DataTypes.TEXT },
  field_mapping: { type: DataTypes.TEXT },
  crawl_schedule: { type: DataTypes.STRING(50) },
  retry_times: { type: DataTypes.INTEGER, defaultValue: 3 },
  retry_interval: { type: DataTypes.INTEGER, defaultValue: 300 },
  status: { type: DataTypes.TINYINT, defaultValue: 1 },
  last_run_at: { type: DataTypes.DATE },
  last_success_at: { type: DataTypes.DATE },
  error_message: { type: DataTypes.TEXT }
}, { tableName: 'data_sources', timestamps: false });

// 每日价格
const DailyPrice = sequelize.define('DailyPrice', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  product_id: { type: DataTypes.INTEGER, allowNull: false },
  price_date: { type: DataTypes.DATEONLY, allowNull: false },
  price_buy: { type: DataTypes.DECIMAL(12, 2) },
  price_sell: { type: DataTypes.DECIMAL(12, 2) },
  price_avg: { type: DataTypes.DECIMAL(12, 2) },
  price_change: { type: DataTypes.DECIMAL(12, 2) },
  price_change_percent: { type: DataTypes.DECIMAL(8, 4) },
  volume: { type: DataTypes.INTEGER },
  turnover: { type: DataTypes.DECIMAL(15, 2) },
  volume_unit: { type: DataTypes.STRING(20) },
  source_id: { type: DataTypes.INTEGER },
  source_type: { type: DataTypes.STRING(20), defaultValue: 'manual' },
  source_remark: { type: DataTypes.STRING(200) },
  status: { type: DataTypes.TINYINT, defaultValue: 1 },
  verified_by: { type: DataTypes.INTEGER },
  verified_at: { type: DataTypes.DATE }
}, { tableName: 'daily_prices', timestamps: false });

// 日统计
const DailyStatistics = sequelize.define('DailyStatistics', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  stat_date: { type: DataTypes.DATEONLY, allowNull: false },
  total_products: { type: DataTypes.INTEGER, defaultValue: 0 },
  rising_count: { type: DataTypes.INTEGER, defaultValue: 0 },
  falling_count: { type: DataTypes.INTEGER, defaultValue: 0 },
  flat_count: { type: DataTypes.INTEGER, defaultValue: 0 },
