  category_stats: { type: DataTypes.TEXT }
}, { tableName: 'daily_statistics', timestamps: false });

// 关联关系
DailyPrice.belongsTo(Product, { foreignKey: 'product_id', as: 'product' });
DailyPrice.belongsTo(DataSource, { foreignKey: 'source_id', as: 'source' });

module.exports = {
  DataSource,
