/**
 * 认证路由
 */

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');
const { User } = require('../models');
const config = require('../config/jwt');
const { SuccessResponse, ErrorResponse } = require('../utils/response');
const { authenticate } = require('../middleware/auth');

// 登录
router.post('/login', [
  body('username').notEmpty().withMessage('用户名不能为空'),
  body('password').notEmpty().withMessage('密码不能为空')
], async (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ code: 400, message: '参数错误', errors: errors.array() });
    }

    const { username, password } = req.body;

    const user = await User.findOne({ where: { username } });
    if (!user) {
      return res.status(401).json(new ErrorResponse(401, '用户名或密码错误'));
    }

    const isValid = await bcrypt.compare(password, user.password);
    if (!isValid) {
      return res.status(401).json(new ErrorResponse(401, '用户名或密码错误'));
    }

    if (user.status !== 1) {
      return res.status(403).json(new ErrorResponse(403, '账户已被禁用'));
    }

    // 生成Token
    const token = jwt.sign(
      { userId: user.id, role: user.role },
      config.secret,
      { expiresIn: config.expiresIn }
    );

    // 更新登录时间
    await user.update({ last_login_at: new Date() });

    res.json(new SuccessResponse({
      token,
      user: {
        id: user.id,
        username: user.username,
        real_name: user.real_name,
        role: user.role
      }
    }));
  } catch (error) {
    next(error);
  }
});

// 获取当前用户信息
router.get('/me', authenticate, async (req, res) => {
  res.json(new SuccessResponse({
    id: req.user.id,
    username: req.user.username,
    real_name: req.user.real_name,
    role: req.user.role
  }));
});

// 修改密码
router.post('/password', authenticate, [
  body('oldPassword').notEmpty(),
  body('newPassword').isLength({ min: 6 })
], async (req, res) => {
  try {
    const { oldPassword, newPassword } = req.body;

    const user = await User.findByPk(req.user.id);
    const isValid = await bcrypt.compare(oldPassword, user.password);

    if (!isValid) {
      return res.status(400).json(new ErrorResponse(400, '原密码错误'));
    }

    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await user.update({ password: hashedPassword });

    res.json(new SuccessResponse(null, '密码修改成功'));
  } catch (error) {
    next(error);
  }
});

module.exports = router;

