/**
 * 价格路由
 */

const express = require('express');
const router = express.Router();
const { Op } = require('sequelize');
const { body, query, validationResult } = require('express-validator');
const { DailyPrice, Product, ProductCategory, ProductGrade } = require('../models');
const { SuccessResponse, ListResponse, ErrorResponse } = require('../utils/response');
const { authenticate, authorize } = require('../middleware/auth');

// 获取价格列表
router.get('/', async (req, res) => {
  try {
    const { 
      page = 1, 
      pageSize = 20, 
      date, 
      categoryId, 
      gradeId, 
      year, 
      keyword,
      sortField = 'price_change_percent',
      sortOrder = 'desc'
    } = req.query;

    const offset = (page - 1) * pageSize;
    const where = {};

    if (date) where.price_date = date;
    if (categoryId) where.category_id = categoryId;
    if (gradeId) where.grade_id = gradeId;
    if (year) where.year = year;
    if (sortField) {
      // 价格排序处理
    }

    const include = [{
      model: Product,
      as: 'product',
      include: [
        { model: ProductCategory, as: 'category', attributes: ['id', 'name'] },
        { model: ProductGrade, as: 'grade', attributes: ['id', 'name'] }
      ]
    }];

    if (keyword) {
      include[0].where = {
        name: { [Op.like]: `%${keyword}%` }
      };
    }

    const { rows: list, count } = await DailyPrice.findAndCountAll({
      where: { ...where, status: 1 },
      include,
      limit: parseInt(pageSize),
      offset,
      order: [[sortField, sortOrder.toUpperCase()]],
      distinct: true
    });

    res.json(new ListResponse(list, { 
      page: parseInt(page), 
      pageSize: parseInt(pageSize), 
      total: count 
    }));
  } catch (error) {
    next(error);
  }
});

// 获取今日价格
router.get('/today', async (req, res) => {
  try {
    const today = new Date().toISOString().split('T')[0];

    const prices = await DailyPrice.findAll({
      where: { price_date: today, status: 1 },
      include: [{
        model: Product,
        as: 'product',
        attributes: ['id', 'code', 'name', 'category_id', 'grade_id', 'year']
      }],
      order: [['price_change_percent', 'DESC']]
    });

    res.json(new SuccessResponse({
      updateTime: new Date().toLocaleString('zh-CN'),
      prices: prices.map(p => ({
        productId: p.product.id,
        productName: p.product.name,
        price: p.price_avg,
        changePercent: p.price_change_percent,
        direction: p.price_change_percent > 0 ? 'up' : p.price_change_percent < 0 ? 'down' : 'flat',
        volume: p.volume
      }))
    }));
  } catch (error) {
    next(error);
  }
});

// 获取单个产品价格
router.get('/:productId', async (req, res) => {
  try {
    const { productId } = req.params;
    const { days = 30 } = req.query;

    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const prices = await DailyPrice.findAll({
      where: {
        product_id: productId,
        price_date: { [Op.between]: [startDate, endDate] },
        status: 1
      },
      order: [['price_date', 'ASC']]
    });

    res.json(new SuccessResponse(prices));
  } catch (error) {
    next(error);
  }
});

// 获取历史价格
router.get('/:productId/history', async (req, res) => {
  try {
    const { productId } = req.params;
    const { startDate, endDate, period = 'day' } = req.query;

    const where = { product_id: productId, status: 1 };
    if (startDate) where.price_date = { [Op.gte]: startDate };
    if (endDate) where.price_date = { ...where.price_date, [Op.lte]: endDate };

    const prices = await DailyPrice.findAll({
      where,
      order: [['price_date', 'ASC']]
    });

    // 计算统计
    const statistics = {
      avgPrice: 0,
      maxPrice: 0,
      minPrice: 0,
      totalVolume: 0,
      totalTurnover: 0
    };

    if (prices.length > 0) {
      const sum = prices.reduce((acc, p) => ({
        avg: acc.avg + (p.price_avg || 0),
        max: Math.max(acc.max, p.price_avg || 0),
        min: Math.min(acc.min === 0 ? p.price_avg : acc.min, p.price_avg || 0),
        volume: acc.volume + (p.volume || 0),
        turnover: acc.turnover + (p.turnover || 0)
      }), { avg: 0, max: 0, min: 0, volume: 0, turnover: 0 });

      statistics.avgPrice = (sum.avg / prices.length).toFixed(2);
      statistics.maxPrice = sum.max;
      statistics.minPrice = sum.min;
      statistics.totalVolume = sum.volume;
      statistics.totalTurnover = sum.turnover.toFixed(2);
    }

    res.json(new SuccessResponse({
      product: { id: productId },
      trend: prices,
      statistics
    }));
  } catch (error) {
    next(error);
  }
});

// 录入价格
router.post('/', authenticate, authorize('admin', 'manager', 'operator'), [
  body('product_id').isInt(),
  body('price_date').isDate(),
  body('price_buy').optional().isNumeric(),
  body('price_sell').optional().isNumeric(),
  body('price_avg').optional().isNumeric()
], async (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ code: 400, message: '参数错误', errors: errors.array() });
    }

    const product = await Product.findByPk(req.body.product_id);
    if (!product) {
      return res.status(404).json(new ErrorResponse(404, '产品不存在'));
    }

    const price = await DailyPrice.create({
      ...req.body,
      source_type: 'manual',
      category_id: product.category_id,
      grade_id: product.grade_id,
      year: product.year,
      status: 0 // 待审核
    });

    res.json(new SuccessResponse(price, '录入成功，待审核'));
  } catch (error) {
    next(error);
  }
});

// 审核价格
router.post('/verify', authenticate, authorize('admin', 'manager'), [
  body('ids').isArray(),
  body('action').isIn(['approve', 'reject'])
], async (req, res) => {
  try {
    const { ids, action, reason } = req.body;
    const status = action === 'approve' ? 1 : 2;

    await DailyPrice.update(
      { 
        status, 
        verified_by: req.user.id,
        verified_at: new Date()
      },
      { where: { id: ids } }
    );

