/**
 * 数据源路由
 */

const express = require('express');
const router = express.Router();
const { body, validationResult } = require('express-validator');
const { DataSource } = require('../models');
const { SuccessResponse, ListResponse, ErrorResponse } = require('../utils/response');
const { authenticate, authorize } = require('../middleware/auth');

// 获取数据源列表
router.get('/', authenticate, async (req, res) => {
  try {
    const sources = await DataSource.findAll({ order: [['created_at', 'DESC']] });
    res.json(new SuccessResponse(sources));
  } catch (error) {
    next(error);
  }
});

// 创建数据源
router.post('/', authenticate, authorize('admin'), [
  body('name').notEmpty(),
  body('type').isIn(['api', 'manual', 'crawler'])
], async (req, res) => {
  try {
    const source = await DataSource.create(req.body);
    res.json(new SuccessResponse(source, '创建成功'));
  } catch (error) {
    next(error);
  }
});

// 测试数据源连接
router.post('/:id/test', authenticate, authorize('admin'), async (req, res) => {
  // TODO: 实现测试连接逻辑
  res.json(new SuccessResponse({ success: true }, '连接测试成功'));
});

// 手动触发同步
router.post('/:id/sync', authenticate, authorize('admin', 'manager'), async (req, res) => {
  // TODO: 实现数据同步逻辑
  res.json(new SuccessResponse({ success: true }, '同步任务已启动'));
});

// 更新数据源
router.put('/:id', authenticate, authorize('admin'), async (req, res) => {
  try {
    const source = await DataSource.findByPk(req.params.id);
    if (!source) {
      return res.status(404).json(new ErrorResponse(404, '数据源不存在'));
    }
    await source.update(req.body);
    res.json(new SuccessResponse(source, '更新成功'));
  } catch (error) {
    next(error);
  }
});

// 删除数据源
router.delete('/:id', authenticate, authorize('admin'), async (req, res) => {
  try {
    const source = await DataSource.findByPk(req.params.id);
    if (!source) {
      return res.status(404).json(new ErrorResponse(404, '数据源不存在'));
    }
    await source.destroy();
    res.json(new SuccessResponse(null, '删除成功'));
  } catch (error) {
    next(error);
  }
});

module.exports = router;

