/**
 * 系统路由
 */

const express = require('express');
const router = express.Router();
const { SystemConfig } = require('../models');
const { SuccessResponse } = require('../utils/response');
const { authenticate, authorize } = require('../middleware/auth');

// 获取系统配置
router.get('/config', async (req, res) => {
  try {
    const configs = await SystemConfig.findAll();
    const configMap = {};
    configs.forEach(c => {
      configMap[c.key] = c.value;
    });
    res.json(new SuccessResponse(configMap));
  } catch (error) {
    next(error);
  }
});

// 更新系统配置
router.put('/config', authenticate, authorize('admin'), async (req, res) => {
  try {
    const { key, value } = req.body;
    await SystemConfig.upsert({ key, value });
    res.json(new SuccessResponse({ key, value }, '配置更新成功'));
  } catch (error) {
    next(error);
  }
});

// 系统运行统计
router.get('/stats', authenticate, async (req, res) => {
  try {
    const { Product, DailyPrice, DataSource } = require('../models');

    const stats = {
      totalProducts: await Product.count({ where: { status: 1 } }),
      todayPrices: await DailyPrice.count({ 
        where: { price_date: new Date().toISOString().split('T')[0] } 
      }),
      totalSources: await DataSource.count({ where: { status: 1 } })
    };

    res.json(new SuccessResponse(stats));
  } catch (error) {
    next(error);
  }
});

module.exports = router;

